import XCTest
@testable import AnswerCaptureCore
final class StabilityTests: XCTestCase { func testStableWindowNeedsFramesAndDuration() { let e = StabilityEvaluator(thresholds: .init(motionLimit: 1, requiredDuration: 1.8, minimumFrames: 10, warmupDuration: 2.5)); let samples = (0..<10).map { MotionSample(time: Double($0) * 0.2, magnitude: 0.1) }; XCTAssertTrue(e.isStable(samples, now: 1.8)); XCTAssertFalse(e.isStable(Array(samples.dropLast()), now: 1.8)) }; func testWarmupIsRequired() { let armer = AutoCaptureArmer(thresholds:.init(motionLimit:1)); let samples = (0..<10).map { MotionSample(time: Double($0) * 0.2, magnitude: 0.1) }; XCTAssertFalse(armer.canCapture(startedAt: 0, now: 1.8, samples: samples)); XCTAssertTrue(armer.canCapture(startedAt: 0, now: 2.5, samples: samples)) }; func testSharpnessTiePrefersCenter() { XCTAssertEqual(SharpnessSelector.best(in: [ .init(index: 0, score: 10), .init(index: 1, score: 10), .init(index: 2, score: 9)])?.index, 1) } }
